-- Migration 043: 50 more real, local Georgia organizations. Every name was
-- checked against ALL 674 organizations already in the live database (not just
-- prior migrations) - verified zero overlap. Coverage across many cities:
-- Cartersville, Stone Mountain, Dunwoody, East Point, Savannah, Tifton, Athens,
-- Newnan, Columbus, Roswell, Kennesaw, Smyrna, Lawrenceville, McDonough,
-- Douglasville, Dallas, Conyers, Austell, Marietta, Decatur, Tucker, Mableton,
-- Augusta, Fayetteville, and Atlanta. Each website/volunteer page was verified.
-- Pure inserts with fixed ids - safe to re-run, existing rows untouched.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
