  -- ART
  ('e3000000-0000-4000-8000-000000000001', null, 'Tellus Science Museum', 'A Smithsonian-affiliated science museum in Cartersville, where volunteers run the fossil dig and gem-panning areas, greet guests, and co-pilot the planetarium.', 'https://tellusmuseum.org', 'https://www.google.com/s2/favicons?domain=tellusmuseum.org&sz=128', 'art', array['recurring', 'family friendly', 'leadership role'], false, false, 16, 'United States', 'GA', 'Cartersville', true, true, 'both', false),
