insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('e4000000-0000-4000-8000-000000000001', 'e3000000-0000-4000-8000-000000000001', 'Run the Fossil Dig or Planetarium', 'art', 'Volunteers staff the fossil dig and gem-panning areas, greet guests, and co-pilot the digital planetarium at the Tellus Science Museum in Cartersville. It is a fun, hands-on role if you love science and working with families. Check the site for current volunteer openings.', array['recurring', 'family friendly', 'leadership role'], 16, false, false, true, '3-4 hrs', 'https://tellusmuseum.org/support/volunteer/', 'https://tellusmuseum.org/support/volunteer/', '2026-01-01T00:00:00Z', 'Cartersville', 'GA'),
  ('e4000000-0000-4000-8000-000000000002', 'e3000000-0000-4000-8000-000000000002', 'Help at ART Station', 'art', 'Volunteers help with theater productions, galleries, classes, and events at ART Station, a community arts center in a historic Stone Mountain trolley barn. It is a welcoming way to support the arts close to home. Reach out through the site to get involved.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://artstation.org/get-involved', 'https://artstation.org/get-involved', '2026-01-01T00:00:00Z', 'Stone Mountain', 'GA'),
  ('e4000000-0000-4000-8000-000000000003', 'e3000000-0000-4000-8000-000000000003', 'Usher at Stage Door Players', 'art', 'Volunteers seat patrons and assist the front-of-house manager at Stage Door Players in Dunwoody, and get to enjoy the shows. It is a great fit if you love live theater. Email the education and engagement director to sign up.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://stagedoortheatrega.org/work-with-us/', 'https://stagedoortheatrega.org/work-with-us/', '2026-01-01T00:00:00Z', 'Dunwoody', 'GA'),
  ('e4000000-0000-4000-8000-000000000004', 'e3000000-0000-4000-8000-000000000004', 'Support Theater for Social Change', 'art', 'Volunteers usher, help at events, and support programs at Out of Hand Theater, which blends theater with civic engagement in Atlanta. Volunteers are trained and matched to a good fit. It is a great role if you care about art and social justice.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://www.outofhandtheater.com/get-involved', 'https://www.outofhandtheater.com/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000005', 'e3000000-0000-4000-8000-000000000005', 'Support a Dance Company', 'art', 'Volunteers help with events, fundraising, and promotion for Ballethnic Dance Theatre in East Point, which uses dance as a catalyst for social change. If you love dance and community, it is a rewarding way to help. Roles are mostly event-based.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://ballethnic.org/volunteer/', 'https://ballethnic.org/volunteer/', '2026-01-01T00:00:00Z', 'East Point', 'GA'),
  ('e4000000-0000-4000-8000-000000000006', 'e3000000-0000-4000-8000-000000000006', 'Support Young Dancers', 'art', 'Volunteers greet guests, help backstage with students, and assist at the annual Holiday Store with Moving in the Spirit, an Atlanta youth-development dance nonprofit. It is a joyful, creative way to support kids and teens. There are roles for many schedules.', array['recurring', 'creative work', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://movinginthespirit.org/volunteer/', 'https://movinginthespirit.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000007', 'e3000000-0000-4000-8000-000000000007', 'Become a Museum Docent', 'art', 'Volunteers train as docents to lead tours for school groups and visitors at the Savannah African Art Museum; no prior art background is needed, and talking points are provided. It is a meaningful fit if you love African art and history. Email a resume to apply.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://www.savannahafricanartmuseum.org/volunteer2a', 'https://www.savannahafricanartmuseum.org/volunteer2a', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e4000000-0000-4000-8000-000000000008', 'e3000000-0000-4000-8000-000000000008', 'Greet Visitors at the Carter Library', 'art', 'Volunteers welcome visitors as museum greeters, and trained docents lead tours, at the Jimmy Carter Presidential Library and Museum in Atlanta. Greeters fill a 3-to-4-hour weekly shift. It is a great fit if you love history and meeting people.', array['recurring', 'leadership role'], 18, false, false, true, '3-4 hrs', 'https://www.jimmycarterlibrary.gov/get-involved/volunteer-and-internships', 'https://www.jimmycarterlibrary.gov/get-involved/volunteer-and-internships', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000009', 'e3000000-0000-4000-8000-000000000009', 'Join the Youth Volunteer Program', 'art', 'Youth 13 to 17 gain hands-on experience in museum operations and historic skills like woodworking and fabric arts through the Georgia Museum of Agriculture''s youth volunteer program in Tifton. Volunteers give about 30 hours in summer and 30 during the school year. It is a great way to learn and earn hours.', array['recurring', 'family friendly', 'counts for school hours'], 13, false, false, true, 'Varies', 'https://gma.abac.edu/support', 'https://gma.abac.edu/support', '2026-01-01T00:00:00Z', 'Tifton', 'GA'),
  ('e4000000-0000-4000-8000-000000000010', 'e3000000-0000-4000-8000-000000000010', 'Sing or Help with a Community Chorus', 'music', 'Volunteers sing with, or help behind the scenes at, the Choral Guild of Atlanta, the city''s longest-running community chorus, which brings choral music to under-served areas. If you love music, it is a great way to be part of it. Roles are concert-season based.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://cgatl.org/', 'https://cgatl.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000011', 'e3000000-0000-4000-8000-000000000011', 'Volunteer at Piedmont Athens', 'medicine', 'Volunteers serve at information desks, in gift shops, and in patient-facing roles across more than 50 departments at Piedmont Athens Regional, with adult, college, and teen programs. A three-month commitment is requested. It is a great fit if you are exploring health care.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.piedmont.org/volunteers/piedmont-athens/volunteer-opportunities', 'https://www.piedmont.org/volunteers/piedmont-athens/volunteer-opportunities', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e4000000-0000-4000-8000-000000000012', 'e3000000-0000-4000-8000-000000000012', 'Volunteer at Piedmont Newnan', 'medicine', 'Adult volunteers 18 and up support patients, families, and staff at Piedmont Newnan hospital after orientation and annual health requirements. It is a strong option if you are interested in health care in Coweta County. Contact the volunteer office to begin.', array['recurring'], 18, false, false, true, '3-4 hrs / week', 'https://www.piedmont.org/volunteers/piedmont-newnan/newnan-volunteer-opportunities', 'https://www.piedmont.org/volunteers/piedmont-newnan/newnan-volunteer-opportunities', '2026-01-01T00:00:00Z', 'Newnan', 'GA'),
  ('e4000000-0000-4000-8000-000000000013', 'e3000000-0000-4000-8000-000000000013', 'Volunteer at Piedmont Columbus', 'medicine', 'Volunteers support patients, families, and staff at Piedmont Columbus Regional. It is a great fit if you are exploring a health career in the Columbus area. Reach out through Piedmont''s volunteer page to get started.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.piedmont.org/get-involved/volunteer', 'https://www.piedmont.org/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e4000000-0000-4000-8000-000000000014', 'e3000000-0000-4000-8000-000000000014', 'Volunteer at Grady', 'medicine', 'Volunteers support patients and families at Grady, one of the nation''s largest public hospitals in downtown Atlanta, committing to at least a year of weekly service. There are roles for students, retirees, and anyone with a heart to help. It is a meaningful fit if you are interested in health care.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.gradyhealth.org/volunteer/', 'https://www.gradyhealth.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000015', 'e3000000-0000-4000-8000-000000000015', 'Volunteer at an Emory Hospital', 'medicine', 'Volunteers greet patients and visitors, support nursing units, and provide administrative help at Emory Healthcare hospitals in Atlanta. Adult volunteers typically commit to a weekly shift for a year. It is a strong fit if you are exploring a health career.', array['recurring', 'counts for school hours'], 18, false, false, true, '4 hrs / week', 'https://www.emoryhealthcare.org/about/volunteering', 'https://www.emoryhealthcare.org/about/volunteering', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000016', 'e3000000-0000-4000-8000-000000000016', 'Provide Companionship in Hospice', 'medicine', 'Volunteers provide companionship, run errands, play music, or share a friendly conversation with hospice patients through Hospice Savannah, with two to four hours a week; teens 16-17 can serve too. It is a gentle, meaningful way to support people and families. Training is provided.', array['recurring'], 16, false, false, true, '2-4 hrs / week', 'https://www.hospicesavannah.org/volunteer/', 'https://www.hospicesavannah.org/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e4000000-0000-4000-8000-000000000017', 'e3000000-0000-4000-8000-000000000017', 'Support Hospice Patients', 'medicine', 'Volunteers 18 and up visit patients, read, play music, provide respite, and run errands, or help with administrative tasks, through Longleaf Hospice serving the Roswell, Atlanta, and Covington areas. Flexible hours average about two a week. It is a caring, meaningful role.', array['recurring'], 18, false, false, true, '2 hrs / week', 'https://longleafhospice.com/contact-us/volunteer', 'https://longleafhospice.com/contact-us/volunteer', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('e4000000-0000-4000-8000-000000000018', 'e3000000-0000-4000-8000-000000000018', 'Refurbish Mobility Equipment', 'medicine', 'Volunteers help refurbish wheelchairs, collect and process medical equipment, and staff the thrift store at FODAC in Stone Mountain, which keeps people with disabilities moving. It is hands-on work with a direct, tangible impact. Great for individuals and groups.', array['recurring', 'good for crews', 'physical work'], 16, false, false, true, '2-3 hrs', 'https://fodac.org/', 'https://fodac.org/', '2026-01-01T00:00:00Z', 'Stone Mountain', 'GA'),
  ('e4000000-0000-4000-8000-000000000019', 'e3000000-0000-4000-8000-000000000019', 'Steward a North Atlanta Preserve', 'environment', 'Volunteers help with trails, water stewardship, and events at the Blue Heron Nature Preserve, a pocket of protected greenspace in north Atlanta. It is satisfying outdoor work close to the city, and a good way to earn hours. Corporate and group workdays are welcome.', array['outdoors', 'physical work', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://bhnp.org/get-involved/volunteer-at-the-blue-heron/', 'https://bhnp.org/get-involved/volunteer-at-the-blue-heron/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000020', 'e3000000-0000-4000-8000-000000000020', 'Protect Land Along the Oconee', 'environment', 'Volunteers join stewardship days and field trips protecting land along the North and Middle Oconee Rivers with the Oconee River Land Trust in Athens. It is a great way to care for local rivers and forests. Members get notice of volunteer fun days.', array['outdoors', 'recurring', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://www.oconeeriverlandtrust.org/', 'https://www.oconeeriverlandtrust.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e4000000-0000-4000-8000-000000000021', 'e3000000-0000-4000-8000-000000000021', 'Maintain Trails or Give Tours', 'environment', 'Volunteers do trail maintenance and cleanups, or serve as Cannon''s Point Preserve docents, with the St. Simons Land Trust on the Georgia coast. It is a beautiful place to give your time and share a love of conservation. Reach out through the site to help.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://sslt.org/take-action/volunteer/', 'https://sslt.org/take-action/volunteer/', '2026-01-01T00:00:00Z', 'St. Simons Island', 'GA'),
  ('e4000000-0000-4000-8000-000000000022', 'e3000000-0000-4000-8000-000000000022', 'Tend the Gardens in Kennesaw', 'gardening', 'Volunteers maintain the collections, lead tours, and help at Community Volunteer Days at Smith-Gilbert Gardens in Kennesaw, where nearly 250 volunteers give 3,500 hours a year. It is hands-on outdoor work for garden lovers. Register on their volunteer page.', array['outdoors', 'physical work', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://smithgilbertgardens.com/support-us/volunteer/', 'https://smithgilbertgardens.com/support-us/volunteer/', '2026-01-01T00:00:00Z', 'Kennesaw', 'GA'),
  ('e4000000-0000-4000-8000-000000000023', 'e3000000-0000-4000-8000-000000000023', 'Help at a Digital-Skills Workshop', 'tech', 'Volunteers support digital-literacy workshops with Inspiredu, an Atlanta nonprofit bridging the digital divide, helping facilitators answer questions and set up. There are in-person and virtual roles. It is a great fit if you care about tech access and equity.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://www.iuatl.org/volunteer', 'https://www.iuatl.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000024', 'e3000000-0000-4000-8000-000000000024', 'Lead a 4-H Club or Camp', 'education', 'Volunteers chaperone 4-H summer camp, lead special-interest teams, or help with club programs through Georgia 4-H, the state''s largest youth-development program. Training is provided. It is a rewarding way to support young people across Georgia.', array['recurring', 'leadership role', 'family friendly'], 18, false, false, true, 'Varies', 'https://georgia4h.org/get-involved/volunteer/', 'https://georgia4h.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e4000000-0000-4000-8000-000000000025', 'e3000000-0000-4000-8000-000000000025', 'Lead a Scout Troop', 'education', 'Volunteers lead troops, mentor youth, and support camps and activities with the Boy Scouts of America Atlanta Area Council across 13 north Georgia counties. The average Scout volunteer gives about 20 hours a month. It is a rewarding, ongoing leadership role.', array['recurring', 'leadership role', 'outdoors'], 18, false, false, true, '2-4 hrs / week', 'https://www.atlantabsa.org/volunteer', 'https://www.atlantabsa.org/volunteer', '2026-01-01T00:00:00Z', 'Smyrna', 'GA'),
  ('e4000000-0000-4000-8000-000000000026', 'e3000000-0000-4000-8000-000000000026', 'Help After School', 'education', 'Volunteers lead STEM kits, workshops, and drives supporting underserved youth through After-School All-Stars Atlanta. No experience is required, just a commitment to kids. It is a great way to make a difference in a student''s day.', array['recurring', 'counts for school hours'], 18, false, false, true, '2-3 hrs', 'https://afterschoolallstars.org/volunteer/', 'https://afterschoolallstars.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000027', 'e3000000-0000-4000-8000-000000000027', 'Mentor Students After School', 'education', 'Volunteers invest about four hours a week mentoring and tutoring students after school at The Path Project community centers inside at-risk mobile-home communities in Georgia. It is a steady, relationship-based role that changes lives. Reach out through the site to help.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '4 hrs / week', 'https://www.pathunited.org/georgia-communities', 'https://www.pathunited.org/georgia-communities', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('e4000000-0000-4000-8000-000000000028', 'e3000000-0000-4000-8000-000000000028', 'Support Youth Prevention Programs', 'education', 'Volunteers support positive youth development and substance-abuse prevention programs, training, and events with GUIDE, Inc. in Gwinnett County. It is a good fit if you want to help young people make healthy choices. Check the site for current opportunities.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://guideinc.org/resources/community-involvement/', 'https://guideinc.org/resources/community-involvement/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('e4000000-0000-4000-8000-000000000029', 'e3000000-0000-4000-8000-000000000029', 'Care for Animals in Bartow', 'animals', 'Volunteers help with animal care, adoptions, and events at the Etowah Valley Humane Society in Cartersville, which relies heavily on volunteers. There are hands-on roles for animal lovers. Reach out through the site to get started.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://etowahvalleyhumane.org/', 'https://etowahvalleyhumane.org/', '2026-01-01T00:00:00Z', 'Cartersville', 'GA'),
  ('e4000000-0000-4000-8000-000000000030', 'e3000000-0000-4000-8000-000000000030', 'Help at a No-Kill Shelter', 'animals', 'Volunteers care for animals and help with adoptions at the volunteer-run Henry County Humane Society in McDonough. Complete an application and attend an orientation to get started. It is a rewarding way to help pets find homes.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://henryhumane.com/volunteer/', 'https://henryhumane.com/volunteer/', '2026-01-01T00:00:00Z', 'McDonough', 'GA'),
  ('e4000000-0000-4000-8000-000000000031', 'e3000000-0000-4000-8000-000000000031', 'Foster a Lab', 'animals', 'Volunteers foster dogs, help transport, and assist at adoption events and home visits with Atlanta Lab Rescue, an all-volunteer rescue for Labs and large-breed mixes. Volunteers are 18 and up. Fostering is a great option if your household can host a dog.', array['recurring', 'family friendly'], 18, false, false, true, 'Varies', 'https://atlantalabrescue.com/volunteer/', 'https://atlantalabrescue.com/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000032', 'e3000000-0000-4000-8000-000000000032', 'Support the Pet Pantry', 'animals', 'Volunteers host the pet pantry, pick up donations, and support events and outreach with the Douglas County GA Humane Society. There are roles for individuals and groups. It is a great fit if you love animals and community.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.douglascountyhumanesociety.com/volunteer', 'https://www.douglascountyhumanesociety.com/volunteer', '2026-01-01T00:00:00Z', 'Douglasville', 'GA'),
  ('e4000000-0000-4000-8000-000000000033', 'e3000000-0000-4000-8000-000000000033', 'Care for Shelter Animals', 'animals', 'Volunteers clean kennels, feed animals, and help care for community cat colonies with the Paulding Humane Society in Dallas, Georgia. It is hands-on work for people who love animals. Reach out through the site to get involved.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.pauldinghumanesociety.com/', 'https://www.pauldinghumanesociety.com/', '2026-01-01T00:00:00Z', 'Dallas', 'GA'),
  ('e4000000-0000-4000-8000-000000000034', 'e3000000-0000-4000-8000-000000000034', 'Pack Food in Newnan', 'community', 'Volunteers process and organize donations and sort and box food for distribution at One Roof Outreach in Newnan, plus office and event help. It is a welcoming, hands-on way to help neighbors in Coweta County. Contact the director to get started.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.oneroofoutreach.org/team-4', 'https://www.oneroofoutreach.org/team-4', '2026-01-01T00:00:00Z', 'Newnan', 'GA'),
  ('e4000000-0000-4000-8000-000000000035', 'e3000000-0000-4000-8000-000000000035', 'Help with Food Distribution', 'community', 'Volunteers help feed neighbors in need, pack carts with food, and take groceries out to clients'' cars at Rockdale Emergency Relief in Conyers. It is a friendly, hands-on way to fight hunger in Rockdale County. Great for individuals and groups.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://myrer.org/', 'https://myrer.org/', '2026-01-01T00:00:00Z', 'Conyers', 'GA'),
  ('e4000000-0000-4000-8000-000000000036', 'e3000000-0000-4000-8000-000000000036', 'Serve at Sweetwater Mission', 'community', 'Volunteers help with food, clothing, and family-support programs, including the Meals on a Mission outreach, at Sweetwater Mission in Austell. Teens and groups are welcome. It is a great way to give back close to home.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.sweetwatermission.org/volunteer-signup', 'https://www.sweetwatermission.org/volunteer-signup', '2026-01-01T00:00:00Z', 'Austell', 'GA'),
  ('e4000000-0000-4000-8000-000000000037', 'e3000000-0000-4000-8000-000000000037', 'Provide Childcare for Moms in Crisis', 'community', 'Volunteers provide a safe, nurturing environment for infants and young children while their mothers get support at Sheltering Grace Ministry in Marietta, which serves homeless pregnant women. Scheduling is flexible. It is a meaningful role for anyone with a heart to serve.', array['recurring', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://shelteringgrace.org/', 'https://shelteringgrace.org/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('e4000000-0000-4000-8000-000000000038', 'e3000000-0000-4000-8000-000000000038', 'Coach a Family Toward Housing', 'community', 'Volunteers serve as Success Coaches, working with a HomeStretch family to set financial goals, budget, and make good decisions on the path to permanent housing in Roswell. It is a deeper, relationship-based role. Training and support are provided.', array['recurring', 'leadership role'], 18, false, false, true, '1-2 hrs / week', 'https://www.homestretch.org/volunteer/', 'https://www.homestretch.org/volunteer/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('e4000000-0000-4000-8000-000000000039', 'e3000000-0000-4000-8000-000000000039', 'Sort Donations for Foster Kids', 'community', 'Volunteers process donations, stock the distribution center, and help foster and kinship families shop for free clothing and supplies at the Foster Care Support Foundation in Roswell. There are roles for individuals and groups. It is a hands-on way to help children in care.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.fostercares.org/', 'https://www.fostercares.org/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('e4000000-0000-4000-8000-000000000040', 'e3000000-0000-4000-8000-000000000040', 'Build Community at L''Arche', 'community', 'Volunteers offer friendship and consistent support to Core Members at L''Arche Atlanta in Decatur, a community of people with and without intellectual and developmental disabilities. It is a warm, relationship-centered role. Reach out through the site to get involved.', array['recurring', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://www.larcheatlanta.org/', 'https://www.larcheatlanta.org/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('e4000000-0000-4000-8000-000000000041', 'e3000000-0000-4000-8000-000000000041', 'Support Independent Living', 'community', 'Volunteers help with programs and events at disABILITY LINK in Tucker, a Center for Independent Living that helps people with disabilities reach their goals. It is a good fit if you care about disability rights and independence. Reach out to learn about roles.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://disabilitylink.org/programs/', 'https://disabilitylink.org/programs/', '2026-01-01T00:00:00Z', 'Tucker', 'GA'),
  ('e4000000-0000-4000-8000-000000000042', 'e3000000-0000-4000-8000-000000000042', 'Support People with Vision Loss', 'community', 'Volunteers support programs, events, and daily services at the Center for the Visually Impaired in Atlanta, the state''s largest nonprofit serving people who are blind or low-vision. Volunteer slots go out monthly by newsletter. It is a meaningful, in-person role.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://cviga.org/volunteer-at-cvi/', 'https://cviga.org/volunteer-at-cvi/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000043', 'e3000000-0000-4000-8000-000000000043', 'Help Neighbors with Low Vision', 'community', 'Volunteers help people who are blind or low-vision live independent lives through Vision Rehabilitation Services of Georgia in the metro Atlanta area. There are many ways to help. Reach out through the site to find a role that fits.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://vrsga.org/', 'https://vrsga.org/', '2026-01-01T00:00:00Z', 'Smyrna', 'GA'),
  ('e4000000-0000-4000-8000-000000000044', 'e3000000-0000-4000-8000-000000000044', 'Strengthen Gwinnett Communities', 'community', 'Volunteers support the Gwinnett Coalition, a nonprofit collaborative connecting people, nonprofits, and resources to strengthen children, families, and communities across Gwinnett County. It is a good fit if you want to help at a systems level. Check the site for opportunities.', array['recurring', 'good for crews'], 16, false, false, true, 'Varies', 'https://gwinnettcoalition.org/', 'https://gwinnettcoalition.org/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('e4000000-0000-4000-8000-000000000045', 'e3000000-0000-4000-8000-000000000045', 'Support Families in Crisis', 'community', 'Volunteers help with food and family-support programs at the Family Life Restoration Center in Mableton, a nonprofit founded on volunteer service. There are roles for individuals and groups. It is a welcoming place to help families get back on their feet.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://flrconline.org/', 'https://flrconline.org/', '2026-01-01T00:00:00Z', 'Mableton', 'GA'),
  ('e4000000-0000-4000-8000-000000000046', 'e3000000-0000-4000-8000-000000000046', 'Sort Donations at the Family Store', 'faith', 'Volunteers sort donations, hang clothing, and restock shelves at The Salvation Army of Augusta''s Family Stores, or help at other community programs. There are roles for individuals and groups. It is a flexible, welcoming way to help neighbors in need.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://southernusa.salvationarmy.org/augusta/volunteer/', 'https://southernusa.salvationarmy.org/augusta/volunteer/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('e4000000-0000-4000-8000-000000000047', 'e3000000-0000-4000-8000-000000000047', 'Strengthen the Community', 'faith', 'Volunteers help power planning, allocation, and community campaigns with the Jewish Federation of Greater Atlanta, the city''s central Jewish community-building organization. Volunteers of all backgrounds are welcome. Explore ways to get involved on their site.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://jewishatlanta.org/get-involved/', 'https://jewishatlanta.org/get-involved/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000048', 'e3000000-0000-4000-8000-000000000048', 'Be a Tennis Coach or Partner', 'sports', 'Volunteers coach, serve as playing partners, umpire, and mentor athletes with intellectual disabilities through Special Pops Tennis in metro Atlanta. Tennis experience is not required, and volunteers can be as young as 8. It is a joyful, active way to help.', array['recurring', 'leadership role', 'family friendly'], 8, false, false, true, '2-3 hrs', 'https://www.specialpopstennis.org/', 'https://www.specialpopstennis.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000049', 'e3000000-0000-4000-8000-000000000049', 'Support Adapted School Sports', 'sports', 'Volunteers help run interscholastic adapted athletics - wheelchair basketball, track, football, and more - for students with disabilities through the American Association of Adapted Sports Programs across Georgia. It is a high-impact way to support inclusive sports. Reach out to help at events.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://adaptedsports.org/', 'https://adaptedsports.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e4000000-0000-4000-8000-000000000050', 'e3000000-0000-4000-8000-000000000050', 'Deliver Meals or Do Home Repairs', 'seniors', 'Volunteers deliver Meals on Wheels or join the tool team doing minor home-safety repairs for homebound seniors through Fayette Senior Services in Fayette County. Routes and projects fit many schedules. It is a rewarding way to help older neighbors stay independent.', array['recurring', 'family friendly'], 16, false, false, true, '1-2 hrs', 'https://fayss.org/volunteer/', 'https://fayss.org/volunteer/', '2026-01-01T00:00:00Z', 'Fayetteville', 'GA')
on conflict (id) do nothing;
